import {PD_EVERY,PD_LIMITS,pdMarks,pdClean,pdDelAct,pdEstimate,pdExport,pdFileName,pdId,pdImport,pdMedia,pdPersist,pdPrepare,pdPutAct,pdPutMedia,pdSize,pdSweep} from './persona-dades.js';
import {PS_TEMPLATES,psAct,psActs,psOwner,psProblems,psReload,psVideoStops} from './persona.js';
import {psForgetThumbs} from './persona-art.js';

// ---------- Activitats personalitzades (0.44): the editor and the actions of the folder ----------
// Only adults use this part, from inside the folder «Activitats personalitzades» of the menu: making an activity (its name, who it is
// for, the mechanic, the photos and videos with the sound of each one, the music), changing it, deleting it, exporting it and importing
// activities. Words are fine here (the pupil never sees this dialog); the activity itself has none.
let PE_H={toast:m=>console.log(m),icon:()=>'',refresh:()=>{}},PE_DRAFT=null,PE_INFO=new Map(),PE_URLS=[],PE_BUSY=0;
export function peSetup(h){PE_H={...PE_H,...h};}
const peEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const peTime=d=>{if(!(d>0))return '';const m=Math.floor(d/60),s=Math.round(d%60);return `${m}:${String(s).padStart(2,'0')}`;};
const peUrl=b=>{if(!b)return '';const u=URL.createObjectURL(b);PE_URLS.push(u);return u;};
async function peInfo(id){if(!id)return null;if(PE_INFO.has(id))return PE_INFO.get(id);const m=await pdMedia(id);if(!m)return null;const {blob,...meta}=m;meta.thumbUrl=m.thumb?peUrl(m.thumb):'';PE_INFO.set(id,meta);return meta;}
const peNew=()=>({id:pdId('pp-'),v:1,name:'',child:'',tpl:'album',items:[],music:null,musicMode:'pimpam',fit:'contain',videoMax:30,order:'list',pauseMode:'every',pauseEvery:5,dark:'mitja',created:Date.now(),updated:Date.now(),fresh:true});
// 0.46 · Vídeo a poc a poc: the moments of the pauses are written as m:ss (or seconds), separated by commas; and read back the same way.
export function peParseMarks(text){return pdMarks(String(text||'').split(/[;,\s]+/).filter(Boolean).map(x=>{const m=x.match(/^(?:(\d+):)?(\d+(?:[.']\d+)?)$/);if(!m)return NaN;return (+(m[1]||0))*60+ +m[2].replace("'",'.');}));}
export const peMarkText=t=>{const m=Math.floor(t/60),r=t-m*60,sec=Math.floor(r),dec=Math.round((r-sec)*10);return `${m}:${String(sec).padStart(2,'0')}${dec?"'"+dec:''}`;};
let PE_PREVIEW=-1;
async function peOpen(id){if(document.querySelector('dialog[open]'))return;const a=id?psAct(id):null;PE_DRAFT=a?structuredClone(a):peNew();PE_INFO=new Map();PE_PREVIEW=-1;
 for(const it of PE_DRAFT.items){await peInfo(it.media);if(it.sound)await peInfo(it.sound);}if(PE_DRAFT.music)await peInfo(PE_DRAFT.music);
 const d=document.createElement('dialog');d.className='dialog ps-editor';d.id='ps-editor';d.setAttribute('aria-label','Activitat personalitzada');document.body.append(d);// a file picker closed without a choice sends a «cancel» that bubbles up to the dialog: only the dialog's own one closes it
 d.addEventListener('cancel',e=>{if(e.target!==d)return;e.preventDefault();peClose();});pePaint();d.showModal();d.querySelector('#pe-name')?.focus();}
function peMarksRow(it,i){const m=PE_INFO.get(it.media);if(m?.kind!=='video')return '';const D=PE_DRAFT,stops=psVideoStops(m.dur||0,D,it),n=Math.max(1,stops.length);
 if(D.pauseMode!=='marks')return `<small class="pe-stops">${n===1?'Es veu sencer d’una pulsació (és més curt que l’interval).':`${n} trossos: ${n} pulsacions per veure’l sencer.`}</small>`;
 return `<div class="pe-marks"><label for="pe-marks-${i}">Pauses (minuts:segons, separades per comes)</label><input id="pe-marks-${i}" data-pe-marks="${i}" value="${peEsc((it.marks||[]).map(peMarkText).join(', '))}" placeholder="0:05, 0:12, 0:30" inputmode="text"><small class="pe-stops" id="pe-stops-${i}">${(it.marks||[]).length?`${n} trossos: ${n} pulsacions per veure’l sencer.`:'Sense cap pausa marcada, es veu sencer d’una pulsació.'}</small>
  ${PE_PREVIEW===i?`<div class="pe-preview"><video id="pe-video" controls playsinline preload="auto"></video><div class="pe-preview-actions"><button type="button" class="btn small primary" data-pe-mark="${i}">＋ Pausa en aquest moment</button><button type="button" class="btn small" data-pe-preview="-1">Fet</button></div></div>`:`<button type="button" class="btn small" data-pe-preview="${i}">▶ Marca les pauses mirant el vídeo</button>`}</div>`;}
function peRow(it,i,n){const m=PE_INFO.get(it.media),s=it.sound?PE_INFO.get(it.sound):null,kind=m?.kind==='video'?'Vídeo':'Foto',I=PE_H.icon,vonly=PS_TEMPLATES[PE_DRAFT.tpl]?.videoOnly;
 return `<li class="pe-item"><span class="pe-no">${i+1}</span>${m?.thumbUrl?`<img src="${m.thumbUrl}" alt="">`:'<span class="pe-noimg"></span>'}<div class="pe-meta"><strong>${kind}${m?.kind==='video'&&m.dur?' · '+peTime(m.dur):''}</strong><small>${peEsc(m?.name||'')} · ${pdSize(m?.size)}${m?.kind==='video'&&!m.sound?' · sense so propi':''}</small>
  ${vonly?(m?.kind==='video'?peMarksRow(it,i):'<small class="pe-stops pe-bad">Aquí només hi poden anar vídeos.</small>'):`<div class="pe-sound">${s?`<span class="pe-chip">♪ ${peEsc(s.name)}${s.dur?' · '+peTime(s.dur):''}</span><button class="btn small" data-pe-unsound="${i}">Treu el so</button>`:`<button class="btn small" data-pe-sound="${i}">♪ Afegeix-hi un so</button>`}</div>`}</div>
  <div class="pe-move"><button class="icon-button" data-pe-up="${i}" aria-label="Puja" ${i===0?'disabled':''}>↑</button><button class="icon-button" data-pe-down="${i}" aria-label="Baixa" ${i===n-1?'disabled':''}>↓</button><button class="icon-button" data-pe-remove="${i}" aria-label="Treu-lo" title="Treu-lo">${I('close')}</button></div></li>`;}
function peSeg(key,list){return `<div class="segmented" role="group">${list.map(([v,l])=>`<button type="button" data-pe-set="${key}" data-value="${v}" class="${String(PE_DRAFT[key])===String(v)?'active':''}" aria-pressed="${String(PE_DRAFT[key])===String(v)}">${l}</button>`).join('')}</div>`;}
function pePaint(){const d=document.querySelector('#ps-editor');if(!d)return;const D=PE_DRAFT,I=PE_H.icon,mus=D.music?PE_INFO.get(D.music):null,problems=psProblems(D,PE_INFO),T=PS_TEMPLATES[D.tpl],total=[...new Set([...D.items.flatMap(it=>[it.media,it.sound]),D.music].filter(Boolean))].reduce((s,id)=>s+(PE_INFO.get(id)?.size||0),0);
 d.innerHTML=`<div class="dialog-head"><div class="dialog-title"><h2>${D.fresh?'Activitat nova':'Edita l’activitat'}</h2><button class="icon-button" data-pe-close aria-label="Tanca sense desar">${I('close')}</button></div><p>Les fotos, els vídeos i la música es desen només en aquest dispositiu. Per portar l’activitat a un altre equip, exporteu-la.</p></div>
 <div class="dialog-body"><div class="form-grid"><div class="field"><label for="pe-name">Nom de l’activitat</label><input id="pe-name" maxlength="60" value="${peEsc(D.name)}" placeholder="Per exemple: La meva família"></div><div class="field"><label for="pe-child">Per a qui és (opcional)</label><input id="pe-child" maxlength="40" value="${peEsc(D.child)}" placeholder="Nom de l’infant"></div></div>
 <h3>Com es juga</h3><div class="pe-tpls" role="group" aria-label="Mecànica">${Object.entries(PS_TEMPLATES).map(([k,t])=>`<button type="button" class="pe-tpl${D.tpl===k?' active':''}" data-pe-tpl="${k}" aria-pressed="${D.tpl===k}"><strong>${t.name}</strong><span>${t.short}</span></button>`).join('')}</div><p class="hint pe-tpl-desc">${T.desc}</p>
 <h3>Fotos i vídeos <small>${D.items.length} de 40${total?' · '+pdSize(total):''}</small></h3><ol class="pe-items">${D.items.map((it,i)=>peRow(it,i,D.items.length)).join('')||'<li class="pe-empty">Encara no hi ha cap foto ni cap vídeo.</li>'}</ol>
 <div class="pe-add"><button type="button" class="btn" data-pe-add ${D.items.length>=40?'disabled':''}>＋ Afegeix ${T.videoOnly?'vídeos':'fotos o vídeos'}</button><span class="hint">${T.videoOnly?'Vídeos MP4 (H.264) o WebM, amb el seu so. Si n’hi ha més d’un, quan se n’acaba un, la pulsació següent comença el següent.':'JPG, PNG o WebP; vídeos MP4 (H.264) o WebM. Les fotos es redueixen a 1920 px. Cada element pot tenir el seu so: una veu, una cançó o un soroll (MP3, M4A, WAV, OGG).'}</span></div>
 ${T.videoOnly?peVideoSettings(D):peShowSettings(D,mus)}
 <div id="pe-status" class="note" role="status" ${PE_BUSY?'':'hidden'}></div><div id="pe-error" class="error" role="alert"></div>${problems.length?`<ul class="pe-problems">${problems.map(p=>`<li>${p}</li>`).join('')}</ul>`:''}
 <input class="hidden" id="pe-files" type="file" accept="${T.videoOnly?'video/*':'image/*,video/*'}" multiple><input class="hidden" id="pe-audio" type="file" accept="audio/*,.mp3,.m4a,.wav,.ogg">
 <div class="dialog-actions">${D.fresh?'<span></span>':`<button type="button" class="btn small pe-danger" data-pe-delete>Esborra l’activitat</button>`}<div class="profile-actions"><button type="button" class="btn small" data-pe-close>Cancel·la</button><button type="button" class="btn primary" data-pe-save ${problems.length||PE_BUSY?'disabled':''}>Desa ${I('check')}</button></div></div></div>`;if(PE_PREVIEW>=0)pePreviewLoad();}
function peVideoSettings(D){return `<h3>Les pauses</h3><div class="field"><label>On s’atura el vídeo</label>${peSeg('pauseMode',[['every','Cada pocs segons'],['marks','Als moments que marqueu']])}</div>
 ${D.pauseMode==='marks'?'<span class="hint">Escriviu els moments a cada vídeo, o obriu-lo i premeu «Pausa en aquest moment» on vulgueu que s’aturi. Al final de cada vídeo sempre s’atura.</span>':`<div class="field"><label>Cada quant s’atura</label>${peSeg('pauseEvery',PD_EVERY.map(n=>[n,n<60?n+' s':'1 min']))}</div>`}
 <div class="field"><label>Enfosquiment a cada pausa</label>${peSeg('dark',[['suau','Suau'],['mitja','Mitjà'],['fort','Fort']])}<span class="hint">El vídeo s’atura i la pantalla s’enfosqueix a poc a poc fins a la pulsació següent; en prémer, s’aclareix i el vídeo continua. El so del vídeo s’apaga suaument just abans de cada pausa.</span></div>
 <h3>Com es mostren</h3><div class="field"><label>Encaix del vídeo</label>${peSeg('fit',[['contain','Sencer'],['cover','Omple la pantalla']])}</div>`;}
function peShowSettings(D,mus){return `<h3>Música de l’activitat</h3>${peSeg('musicMode',[['pimpam','Instruments de Pim Pam'],['own','Una cançó pròpia'],['none','Sense música']])}
 ${D.musicMode==='own'?`<div class="pe-sound">${mus?`<span class="pe-chip">♪ ${peEsc(mus.name)}${mus.dur?' · '+peTime(mus.dur):''}</span>`:''}<button type="button" class="btn small" data-pe-music>${mus?'Canvia la cançó':'Tria la cançó'}</button></div><span class="hint">La cançó sona mentre es veu cada foto i continua on s’havia quedat a la pulsació següent.</span>`:`<span class="hint">${D.musicMode==='none'?'Només sonaran els sons propis de cada element i el so dels vídeos.':'Les fotos sense so propi sonen amb arpa, marimba, kalimba i violoncels de Pim Pam.'}</span>`}
 <h3>Com es mostren</h3><div class="form-grid"><div class="field"><label>Encaix de les fotos</label>${peSeg('fit',[['contain','Sencera'],['cover','Omple la pantalla']])}</div><div class="field"><label>Ordre</label>${peSeg('order',[['list','En ordre'],['shuffle','A l’atzar']])}</div><div class="field"><label>Durada màxima dels vídeos</label>${peSeg('videoMax',[[15,'15 s'],[30,'30 s'],[60,'1 min'],[180,'3 min']])}</div></div>
 <span class="hint">Una foto es veu el temps de «Durada de l’efecte» de la configuració, o tot el que dura el seu so. El nombre de passos de «Descobreix pas a pas» és a la configuració, i el temps d’espera de «Qui s’amaga?», al menú de configuració de dins de l’activitat.</span>`;}
// The video of the editor's preview, to mark the pauses while it is watched: its file is read from the device when it opens.
async function pePreviewLoad(){const i=PE_PREVIEW,it=PE_DRAFT?.items[i],el=document.querySelector('#pe-video');if(!it||!el)return;try{const m=await pdMedia(it.media);if(!m?.blob||PE_PREVIEW!==i||!el.isConnected)return;el.src=peUrl(m.blob);}catch{}}
function peMarksChanged(i){const it=PE_DRAFT.items[i],m=PE_INFO.get(it?.media),el=document.querySelector('#pe-stops-'+i);if(!el||!m)return;const n=psVideoStops(m.dur||0,PE_DRAFT,it).length;el.textContent=(it.marks||[]).length?`${n} trossos: ${n} pulsacions per veure’l sencer.`:'Sense cap pausa marcada, es veu sencer d’una pulsació.';}
function peStatus(msg){const el=document.querySelector('#pe-status');if(!el)return;el.hidden=!msg;el.textContent=msg||'';}
function peError(msg){const el=document.querySelector('#pe-error');if(el)el.textContent=msg||'';}
function peKeepFields(){const n=document.querySelector('#pe-name'),c=document.querySelector('#pe-child');if(n)PE_DRAFT.name=n.value;if(c)PE_DRAFT.child=c.value;}
// The files chosen are prepared one after the other (a photo is made smaller, a video is checked by playing it) and stored at once, so a
// big video never stays only in memory; until the activity is saved they belong to nobody, and closing without saving deletes them.
async function peAddFiles(files,target){peKeepFields();const list=[...files],errors=[];PE_BUSY++;pePaint();
 for(let k=0;k<list.length;k++){const f=list[k];peStatus(list.length>1?`Preparant ${k+1} de ${list.length}: ${f.name}…`:`Preparant ${f.name}…`);
  try{if(target==='items'&&PE_DRAFT.items.length>=40){errors.push('Com a màxim hi pot haver 40 fotos o vídeos.');break;}const m=await pdPrepare(f,target==='items'?['image','video']:['audio']);await pdPutMedia(m);const {blob,...meta}=m;meta.thumbUrl=m.thumb?peUrl(m.thumb):'';PE_INFO.set(m.id,meta);
   if(target==='items')PE_DRAFT.items.push({id:pdId('i'),media:m.id,sound:null});else if(target==='music')PE_DRAFT.music=m.id;else if(typeof target==='number'&&PE_DRAFT.items[target])PE_DRAFT.items[target].sound=m.id;}
  catch(e){errors.push(e?.name==='QuotaExceededError'?'No hi ha prou espai al dispositiu per desar aquest fitxer.':e?.message||String(e));}}
 PE_BUSY--;pePaint();peError(errors.join(' '));peStatus('');}
let peTarget='items';
async function peSave(){peKeepFields();const D=PE_DRAFT;if(psProblems(D,PE_INFO).length)return;D.name=D.name.trim()||(D.child?`Les fotos de ${D.child}`:'La meva activitat');D.updated=Date.now();D.owner=D.owner||psOwner();const clean=pdClean(D);if(D.musicMode!=='own'||PS_TEMPLATES[D.tpl]?.videoOnly)clean.music=null;
 try{await pdPutAct(clean);await pdPersist();PE_DRAFT=null;peDispose();await pdSweep();psForgetThumbs();await psReload();PE_H.refresh();PE_H.toast(D.fresh?'Activitat creada. Es desa només en aquest dispositiu.':'Canvis desats.');}catch(e){peError('No s’ha pogut desar: '+(e?.message||e));}}
function peDispose(){const d=document.querySelector('#ps-editor');if(d){d.close();d.remove();}for(const u of PE_URLS)URL.revokeObjectURL(u);PE_URLS=[];PE_INFO=new Map();}
async function peClose(){PE_DRAFT=null;peDispose();try{await pdSweep();}catch{}PE_H.refresh();}
async function peDelete(id){const a=psAct(id);if(!a)return;if(!confirm(`Voleu esborrar «${a.name}»? S’esborra d’aquest dispositiu i no es pot desfer. Si la voleu conservar, exporteu-la abans.`))return;
 await pdDelAct(id);await pdSweep();psForgetThumbs();await psReload();if(document.querySelector('#ps-editor'))peDispose();PE_H.refresh();PE_H.toast('Activitat esborrada.');}
function peDownload(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),60000);}
async function peExport(id){const acts=id?[psAct(id)].filter(Boolean):psActs();if(!acts.length){PE_H.toast('Encara no hi ha cap activitat per exportar.');return;}PE_H.toast('Preparant l’exportació…');
 try{const zip=await pdExport(acts);peDownload(zip,id?pdFileName(acts[0].name):pdFileName('activitats-personalitzades-'+new Date().toISOString().slice(0,10)));PE_H.toast(`${acts.length===1?'Activitat exportada':acts.length+' activitats exportades'} (${pdSize(zip.size)}).`);}catch(e){PE_H.toast('No s’ha pogut exportar: '+(e?.message||e));}}
async function peImport(file){if(!file)return;PE_H.toast('Important…');try{const r=await pdImport(file,null,psOwner());await pdPersist();psForgetThumbs();await psReload();PE_H.refresh();
 PE_H.toast(r.added.length?`${r.added.length===1?'S’ha importat 1 activitat':`S’han importat ${r.added.length} activitats`}${r.skipped?` (${r.skipped} ja hi eren)`:''}.`:r.skipped?'Aquestes activitats ja hi eren.':'El fitxer no tenia activitats.');}
 catch(e){try{await pdSweep();}catch{}PE_H.toast(e?.name==='QuotaExceededError'?'No hi ha prou espai al dispositiu per importar-les.':'No s’ha pogut importar: '+(e?.message||e));}}
async function peStorageLine(){const e=await pdEstimate();if(!e||!e.quota)return '';return `Espai ocupat en aquest navegador: ${pdSize(e.used)} · disponible: ${pdSize(Math.max(0,e.quota-e.used))}`;}
// the clicks and the inputs of the editor (one set of listeners for the whole page)
if(typeof document!=='undefined'){document.addEventListener('click',e=>{const b=e.target.closest('#ps-editor button');if(!b||!PE_DRAFT)return;const D=PE_DRAFT,ds=b.dataset;
  if('peClose' in ds){peClose();return;}if('peSave' in ds){peSave();return;}if('peDelete' in ds){peDelete(D.id);return;}peKeepFields();
  if(ds.peTpl){D.tpl=ds.peTpl;PE_PREVIEW=-1;pePaint();return;}if(ds.peSet){const v=ds.value;D[ds.peSet]=ds.peSet==='videoMax'||ds.peSet==='pauseEvery'?+v:v;pePaint();return;}
  if(ds.pePreview!==undefined){PE_PREVIEW=+ds.pePreview;pePaint();return;}
  if(ds.peMark!==undefined){const i=+ds.peMark,v=document.querySelector('#pe-video'),it=D.items[i];if(!v||!it)return;const t=v.currentTime||0;if(t<.3){peError('Feu córrer el vídeo fins al moment de la pausa i torneu a prémer.');return;}peError('');it.marks=pdMarks([...(it.marks||[]),t]);const inp=document.querySelector('#pe-marks-'+i);if(inp)inp.value=it.marks.map(peMarkText).join(', ');peMarksChanged(i);return;}
  if('peAdd' in ds){peTarget='items';document.querySelector('#pe-files')?.click();return;}if('peMusic' in ds){peTarget='music';document.querySelector('#pe-audio')?.click();return;}
  if(ds.peSound!==undefined){peTarget=+ds.peSound;document.querySelector('#pe-audio')?.click();return;}if(ds.peUnsound!==undefined){D.items[+ds.peUnsound].sound=null;pePaint();return;}
  const swap=(i,j)=>{if(j<0||j>=D.items.length)return;[D.items[i],D.items[j]]=[D.items[j],D.items[i]];pePaint();};
  if(ds.peUp!==undefined)swap(+ds.peUp,+ds.peUp-1);else if(ds.peDown!==undefined)swap(+ds.peDown,+ds.peDown+1);else if(ds.peRemove!==undefined){D.items.splice(+ds.peRemove,1);pePaint();}});
 document.addEventListener('change',e=>{const t=e.target;if(t.id==='pe-files'&&t.files?.length)peAddFiles(t.files,'items');else if(t.id==='pe-audio'&&t.files?.length)peAddFiles([t.files[0]],peTarget);});
 document.addEventListener('input',e=>{if(e.target.id==='pe-name'||e.target.id==='pe-child')peKeepFields();if(e.target.dataset?.peMarks!==undefined&&PE_DRAFT){const i=+e.target.dataset.peMarks,it=PE_DRAFT.items[i];if(it){it.marks=peParseMarks(e.target.value);peMarksChanged(i);}}});}
export const PE_LIMITS=PD_LIMITS;
export {peOpen,peDelete,peExport,peImport,peStorageLine};
